class Solution { public int sumOfFlooredPairs(int[] nums){int maximum=Arrays.stream(nums).max().getAsInt();int[] frequency=new int[maximum+1],prefix=new int[maximum+1];for(int value:nums)frequency[value]++;for(int value=1;value<=maximum;value++)prefix[value]=prefix[value-1]+frequency[value];long answer=0;for(int divisor=1;divisor<=maximum;divisor++)if(frequency[divisor]>0)for(int start=divisor;start<=maximum;start+=divisor){int count=prefix[Math.min(maximum,start+divisor-1)]-prefix[start-1];answer=(answer+(long)frequency[divisor]*(start/divisor)*count)%1_000_000_007;}return (int)answer;} }
